   WHERE o.match_hash = ANY (ARRAY['ea24226f5beea542145fc4b47de3144b', '0fd35997fe15e79874bba6edd5f015bf', '692fa1f5dd220a9dd4e07b268b0b6044', '6ab6bd13bd4950c7239c4402664025e3', '2a7e00f99777371352c36a9174f9ff68', '5720ee15faad2a14821a42058eb6dc72', '8c9afdbde8d5e1683bb228764f5d3409', '36ef49bc57fbdc19f6368e64d33d12cb', 'c2338050bc580f92fad05b20f8df0c97', '352c9a443ef815332ff0db7d2963f37e', 'b1aa46a204d246ef6dcb7be791ae5db3', '6ea493d906a7f5770462f92f7242c85b', '84838504521a419b850fde02858be43c', '2c57356e9481cbf2d35af548b9aa00f3', '26ccfb778179df167aee65ac424cc8ff', 'cdc67bff2d0b6537b577e16ecf0207a2', '787972ebf2748ce53dad5fe0d062666c', '90a30910b5d12d56c662a15708c1a814', '4cf506ced4ea488632d3a8125b41ee0e', '999b77da901357cb9cf5801130995b14', '6b8bfd825111a36a86d72c2b8bed1520', '659f1c07a94b5290fdac33cbb4036d6e', '495f7cab159b11842d77a3279e201eef', 'f8645dcb9b0694be993e642057e3ffa3', 'df4b92d5911c0e39e116ae7b1a56f49d', '95c552dc9d281f6c14c4bb905147e27e', '524a8b17d2ea3e9e31ff288a27bb60ca', '3f5ef248a0eeeb7ab87f356482d452fb', 'a3f82abd5e338722d6cc745482bac80f', '84d9e672f38d9f3c805cbed009d519e2', '74831bf0b46820e4668289138409ef7e', '6dede0337593cd26e11de7715d00350e', '5e53bb7b8368bfddfae1b296cfc32646', 'e029cd0474236219fb20967086034cbd', '1d57195589737303353e9de080bd5215', '22c54bf96d94aa919649f7355185564a', '96ef205c5edaa714a581ecf7e2d5140e', '151dc90055d4d6692f693ea221a41f96', '6c8a7d69cce86bff1af03d7073dfba4f', 'b887aeaace2e87f7752378c40c7e4b6b', 'b094e4ee152ea05a86847e6537bffce4']::text[])
     AND length(k.kw) >= 4
     -- Número solto NÃO é chave de match: testado contra o firehose real do Bluesky,
     -- '1000'/'2026' casavam com qualquer conversa (29 falsos positivos em 55s).
     AND k.kw !~ '^[0-9 .]+$'
   -- Comissão maior ganha a keyword compartilhada (do nada, o melhor anúncio paga).
   ORDER BY (o.commission_rate_pct IS NULL), o.commission_rate_pct DESC, o.match_hash
  ON CONFLICT (keyword) DO NOTHING;

  -- -------------------------------------------------------------------------
  -- 4) Conferência (esperado: 500 produtos + 200 lojas + 1 categoria = 701)
  -- -------------------------------------------------------------------------
  SELECT count(*) INTO v_total FROM public.nexus_shopee_offers;
  SELECT count(*) INTO v_kw    FROM public.nexus_brand_keywords WHERE kind LIKE 'shopee%';
  v_msg := format('v330.0 — nexus_shopee_offers=%s ; keywords_shopee=%s', v_total, v_kw);
  RAISE NOTICE '%', v_msg;

  PERFORM set_config('nexus.v330_status', v_status, false);
  PERFORM set_config('nexus.v330_msg',    v_msg,    false);

EXCEPTION WHEN OTHERS THEN
  -- Falha silenciosa e controlada: não derruba o pool do PostgREST (57014/timeout).
  RAISE WARNING 'v330.0 abortado (%). Nada foi aplicado.', SQLERRM;
  PERFORM set_config('nexus.v330_status', 'ABORTADO', false);
  PERFORM set_config('nexus.v330_msg',    SQLERRM,    false);
END
$v330$;

COMMIT;

-- Telemetria do job (o painel lê isto para saber que a onda passou).
VALUES ('v330-shopee-ingest', current_setting('nexus.v330_status', true),
        left(coalesce(current_setting('nexus.v330_msg', true), 'sem mensagem'), 400));
